def test_filter_map(self):
    actual = list(
        mi.filter_map(
            lambda x: int(x) if x.isnumeric() else None,
            ['1', 'a', '2', 'b', '3'],
        )
    )
    expected = [1, 2, 3]
    self.assertEqual(actual, expected)
